-- Purpose-scoped source learning. Credentials and live authority are never portable.
CREATE TABLE learning_sources(id TEXT PRIMARY KEY,name TEXT NOT NULL,provider TEXT NOT NULL CHECK(provider IN('orbit','native')),installation_id TEXT,resource_ids_json TEXT NOT NULL,use_basis TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('active','disconnected','held')),version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE learning_investigations(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES learning_sources(id),question TEXT NOT NULL,purpose TEXT NOT NULL,native_evidence_ids_json TEXT NOT NULL,native_request_ids_json TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('active','paused','revoked','held')),native_operator_id TEXT NOT NULL,operator_version INTEGER NOT NULL,actor_id TEXT NOT NULL REFERENCES operators(id),expires_at TEXT NOT NULL,budget_micros INTEGER NOT NULL CHECK(budget_micros>=0),spent_micros INTEGER NOT NULL DEFAULT 0 CHECK(spent_micros>=0),max_run_cost_micros INTEGER NOT NULL CHECK(max_run_cost_micros>0),interval_minutes INTEGER NOT NULL CHECK(interval_minutes>=15),next_run_at TEXT NOT NULL,last_reason TEXT,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE learning_observations(id TEXT PRIMARY KEY,investigation_id TEXT NOT NULL REFERENCES learning_investigations(id) ON DELETE CASCADE,source_id TEXT NOT NULL REFERENCES learning_sources(id),event_key TEXT NOT NULL,content_hash TEXT NOT NULL,wording TEXT NOT NULL,original_json TEXT NOT NULL,observed_at TEXT NOT NULL,source_person_id TEXT,requester_id TEXT REFERENCES requesters(id),account_id TEXT REFERENCES accounts(id),evidence_id TEXT REFERENCES evidence_items(id),request_id TEXT REFERENCES requests(id),created_at TEXT NOT NULL,UNIQUE(investigation_id,event_key,content_hash));
CREATE TABLE learning_artifacts(id TEXT PRIMARY KEY,investigation_id TEXT NOT NULL REFERENCES learning_investigations(id) ON DELETE CASCADE,version INTEGER NOT NULL,input_hash TEXT NOT NULL,body_json TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('current','superseded','contested')),deferred INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,UNIQUE(investigation_id,input_hash));
CREATE TABLE learning_contributions(artifact_id TEXT NOT NULL REFERENCES learning_artifacts(id) ON DELETE CASCADE,observation_id TEXT NOT NULL REFERENCES learning_observations(id) ON DELETE CASCADE,PRIMARY KEY(artifact_id,observation_id));
CREATE TABLE learning_corrections(id TEXT PRIMARY KEY,investigation_id TEXT NOT NULL REFERENCES learning_investigations(id) ON DELETE CASCADE,artifact_id TEXT NOT NULL REFERENCES learning_artifacts(id) ON DELETE CASCADE,correction TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES operators(id),created_at TEXT NOT NULL);
CREATE TABLE learning_commitments(id TEXT PRIMARY KEY,investigation_id TEXT NOT NULL REFERENCES learning_investigations(id) ON DELETE CASCADE,artifact_id TEXT NOT NULL REFERENCES learning_artifacts(id) ON DELETE CASCADE,snapshot_json TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES operators(id),created_at TEXT NOT NULL,UNIQUE(artifact_id));
CREATE TABLE learning_runs(id TEXT PRIMARY KEY,investigation_id TEXT NOT NULL REFERENCES learning_investigations(id) ON DELETE CASCADE,event_key TEXT NOT NULL,claim TEXT NOT NULL,grant_version INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN('running','complete','refused','uncertain')),reserved_micros INTEGER NOT NULL,actual_micros INTEGER,reason TEXT,cursor_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL,finished_at TEXT,UNIQUE(investigation_id,event_key));
CREATE UNIQUE INDEX learning_one_claim ON learning_runs(investigation_id) WHERE state='running';
-- Hash fences survive erasure; they carry no source text or identity.
CREATE TABLE learning_erased_events(source_id TEXT NOT NULL,event_hash TEXT NOT NULL,PRIMARY KEY(source_id,event_hash));
CREATE TABLE learning_erased_people(source_id TEXT NOT NULL,person_hash TEXT NOT NULL,PRIMARY KEY(source_id,person_hash));
CREATE TRIGGER learning_original_immutable BEFORE UPDATE ON learning_observations BEGIN SELECT RAISE(ABORT,'learning_original_immutable'); END;
CREATE TRIGGER learning_snapshot_immutable BEFORE UPDATE ON learning_commitments BEGIN SELECT RAISE(ABORT,'learning_snapshot_immutable'); END;
CREATE TRIGGER learning_artifact_immutable BEFORE UPDATE OF body_json,input_hash,investigation_id,version ON learning_artifacts BEGIN SELECT RAISE(ABORT,'learning_artifact_immutable'); END;
CREATE TABLE learning_source_people(observation_id TEXT NOT NULL REFERENCES learning_observations(id) ON DELETE CASCADE,source_person_id TEXT NOT NULL,PRIMARY KEY(observation_id,source_person_id));
CREATE TABLE learning_invalidations(commitment_id TEXT PRIMARY KEY REFERENCES learning_commitments(id) ON DELETE CASCADE,reason TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TRIGGER learning_contested_commitments AFTER UPDATE OF state ON learning_artifacts WHEN NEW.state='contested' BEGIN
 INSERT OR IGNORE INTO learning_invalidations(commitment_id,reason,created_at) SELECT id,'source_or_interpretation_corrected',strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM learning_commitments WHERE artifact_id=NEW.id;
END;
CREATE TRIGGER learning_native_evidence_correction AFTER INSERT ON evidence_versions BEGIN
 UPDATE learning_artifacts SET state='contested' WHERE id IN(SELECT c.artifact_id FROM learning_contributions c JOIN learning_observations o ON o.id=c.observation_id WHERE o.evidence_id=NEW.evidence_id);
 UPDATE learning_investigations SET version=version+1,last_reason='native_evidence_corrected' WHERE id IN(SELECT investigation_id FROM learning_observations WHERE evidence_id=NEW.evidence_id);
END;
CREATE TRIGGER learning_native_request_correction AFTER UPDATE OF title,description ON requests WHEN NEW.title IS NOT OLD.title OR NEW.description IS NOT OLD.description BEGIN
 UPDATE learning_artifacts SET state='contested' WHERE id IN(SELECT c.artifact_id FROM learning_contributions c JOIN learning_observations o ON o.id=c.observation_id WHERE o.request_id=NEW.id);
 UPDATE learning_investigations SET version=version+1,last_reason='native_request_corrected' WHERE id IN(SELECT investigation_id FROM learning_observations WHERE request_id=NEW.id);
END;

